CELL = 32
@cells = Hash.new { |h, k| h[k] = [] }

def insert(e)
  @cells[[(e.x / CELL).floor, (e.y / CELL).floor]] << e
end

def near(x, y, r)
  xs = ((x - r) / CELL).floor..((x + r) / CELL).floor
  ys = ((y - r) / CELL).floor..((y + r) / CELL).floor
  xs.flat_map { |cx| ys.flat_map { |cy| @cells[[cx, cy]] } }
    .select { |e| (e.x - x)**2 + (e.y - y)**2 <= r * r }
end
